INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3742032, 526115, 41794, '<td valign="top">This has to be one of the best infrared (if I am terming that correctly) photos I have seen. I like the ones with water which we see often, but this really strikes a chord with me. Maybe because I am fascinated by the ancient world. Beautiful photo!</td>', 'This has to be one of the best infrared (if I am terming that correctly) photos I have seen. I like the ones with water which we see often, but this really strikes a chord with me. Maybe because I am fascinated by the ancient world. Beautiful photo!', '2007-06-05 14:58:17.000000', NULL, 1),
(3742036, 526513, 41794, '<td valign="top">Striking composition and the use of the available lighting is fantastic. Almost looks more like a painting than a photo.</td>', 'Striking composition and the use of the available lighting is fantastic. Almost looks more like a painting than a photo.', '2007-06-05 14:58:56.000000', NULL, 1),
(3742114, 526962, 41794, '<td valign="top">This has to be the best photo in the challenge - if this does not ribbon I will be hugely disappointed. Fantastic lighting, great detail and such wonderful expression captured on both of their faces. Had to come back and bump this up.</td>', 'This has to be the best photo in the challenge - if this does not ribbon I will be hugely disappointed. Fantastic lighting, great detail and such wonderful expression captured on both of their faces. Had to come back and bump this up.', '2007-06-05 15:16:55.000000', NULL, 1),
(3742120, 527228, 41794, '<td valign="top">I always find elephants to be a hard subject to photograph. I can never seem to really justify the textures of their skin nor their gentle nature. You have done both with this wonderful photo. They look like they are sharing a private moment of rememberance between them.</td>', 'I always find elephants to be a hard subject to photograph. I can never seem to really justify the textures of their skin nor their gentle nature. You have done both with this wonderful photo. They look like they are sharing a private moment of rememberance between them.', '2007-06-05 15:18:46.000000', NULL, 1),
(3742123, 527613, 41794, '<td valign="top">I love the sense of speed, motion and grace that you have captured with this shot.</td>', 'I love the sense of speed, motion and grace that you have captured with this shot.', '2007-06-05 15:19:55.000000', NULL, 1),
(3742125, 527414, 41794, '<td valign="top">I actually chuckled out loud when I saw this shot. Great capture!</td>', 'I actually chuckled out loud when I saw this shot. Great capture!', '2007-06-05 15:20:44.000000', NULL, 1),
(3742160, 527049, 67258, '<td valign="top">Well spotted!  I do like the added interest of the elderly gentleman.  Well composed ad processed, and fits the challenge perfectly.</td>', 'Well spotted!  I do like the added interest of the elderly gentleman.  Well composed ad processed, and fits the challenge perfectly.', '2007-06-05 15:30:33.000000', NULL, 1),
