(3745445, 527181, 51793, '<td valign="top">Isn''t that 1.5?</td>', 'Isn''t that 1.5?', '2007-06-06 04:09:36.000000', NULL, 1),
(3745447, 527655, 51793, '<td valign="top">beautiful... I like the idea that you used a solid dark blue background to shot off the light blues and cyans. Yellow being the opp. of blue, it really pulls the yellows out too. Great work and set up. I can really tell that you took your time with this. 10</td>', 'beautiful... I like the idea that you used a solid dark blue background to shot off the light blues and cyans. Yellow being the opp. of blue, it really pulls the yellows out too. Great work and set up. I can really tell that you took your time with this. 10', '2007-06-06 04:11:03.000000', NULL, 1),
(3745449, 526650, 51793, '<td valign="top">How cute. Good job getting them to do the same thing at the same time. Lighting looks good too, what did you use?</td>', 'How cute. Good job getting them to do the same thing at the same time. Lighting looks good too, what did you use?', '2007-06-06 04:11:42.000000', NULL, 1),
(3745465, 526551, 33352, '<td valign="top">Good use of the lighting</td>', 'Good use of the lighting', '2007-06-06 04:21:28.000000', NULL, 1),
(3745467, 526984, 33352, '<td valign="top">Like the combination of light and color.</td>', 'Like the combination of light and color.', '2007-06-06 04:22:06.000000', NULL, 1),
(3745469, 526102, 33352, '<td valign="top">very good photography and processing..</td>', 'very good photography and processing..', '2007-06-06 04:22:43.000000', NULL, 1),
(3745473, 527336, 33352, '<td valign="top">like the tone effect achieved here...</td>', 'like the tone effect achieved here...', '2007-06-06 04:23:24.000000', NULL, 1),
(3745475, 527660, 33352, '<td valign="top">Should be a front page finish,IMHO</td>', 'Should be a front page finish,IMHO', '2007-06-06 04:24:12.000000', NULL, 1),
(3745480, 526962, 33352, '<td valign="top">This is an amazing photo, of light and feel,</td>', 'This is an amazing photo, of light and feel,', '2007-06-06 04:26:34.000000', NULL, 1),
(3745994, 525821, 45829, '<td valign="top">Nice.  The fence intrudes and this might be better if it was removed.</td>', 'Nice.  The fence intrudes and this might be better if it was removed.', '2007-06-06 09:20:03.000000', NULL, 1),
(3745997, 527599, 45829, '<td valign="top">With less black on the right, the crop might be improved.</td>', 'With less black on the right, the crop might be improved.', '2007-06-06 09:20:52.000000', NULL, 1),
(3746006, 527304, 45829, '<td valign="top">What happened to focusing?</td>', 'What happened to focusing?', '2007-06-06 09:22:29.000000', NULL, 1),
