(3746012, 527456, 45829, '<td valign="top">The trees are distracting.  Image would be a crisp abstraction without them.</td>', 'The trees are distracting.  Image would be a crisp abstraction without them.', '2007-06-06 09:23:46.000000', NULL, 1),
(3746014, 527620, 45829, '<td valign="top">The plate is very busy.</td>', 'The plate is very busy.', '2007-06-06 09:24:00.000000', NULL, 1),
(3746019, 526649, 45829, '<td valign="top">Nice.</td>', 'Nice.', '2007-06-06 09:24:31.000000', NULL, 1),
(3746023, 526415, 45829, '<td valign="top">There seems to be too many stories going on here.</td>', 'There seems to be too many stories going on here.', '2007-06-06 09:25:04.000000', NULL, 1),
(3746026, 527397, 45829, '<td valign="top">What happened to the focus?</td>', 'What happened to the focus?', '2007-06-06 09:25:24.000000', NULL, 1),
(3746034, 527174, 45829, '<td valign="top">What happened to the focus?</td>', 'What happened to the focus?', '2007-06-06 09:26:47.000000', NULL, 1),
(3746035, 527575, 45829, '<td valign="top">The offset crop is distracting.</td>', 'The offset crop is distracting.', '2007-06-06 09:27:00.000000', NULL, 1),
(3746047, 527073, 45829, '<td valign="top">Try flipping the canvas horizontally.  It reads better.</td>', 'Try flipping the canvas horizontally.  It reads better.', '2007-06-06 09:29:10.000000', NULL, 1),
(3746051, 527152, 45829, '<td valign="top">Try a tighter crop on the left.</td>', 'Try a tighter crop on the left.', '2007-06-06 09:29:54.000000', NULL, 1),
(3746057, 527689, 45829, '<td valign="top">What happened to the focus?</td>', 'What happened to the focus?', '2007-06-06 09:31:17.000000', NULL, 1),
