(3746063, 527616, 45829, '<td valign="top">Try a tighter crop on the left.</td>', 'Try a tighter crop on the left.', '2007-06-06 09:32:55.000000', NULL, 1),
(3746067, 527474, 45829, '<td valign="top">Except...one eye is not blue?</td>', 'Except...one eye is not blue?', '2007-06-06 09:33:14.000000', NULL, 1),
