(3746071, 526321, 45829, '<td valign="top">What happened to the focus?</td>', 'What happened to the focus?', '2007-06-06 09:33:41.000000', NULL, 1),
(3746074, 524464, 45829, '<td valign="top">The photoshop work is distracting - they do not look like apples.</td>', 'The photoshop work is distracting - they do not look like apples.', '2007-06-06 09:34:33.000000', NULL, 1),
(3746075, 523860, 45829, '<td valign="top">What happened to the focus.</td>', 'What happened to the focus.', '2007-06-06 09:34:45.000000', NULL, 1),
(3746082, 526624, 45829, '<td valign="top">Humorous concept. The background is very distracting.  Would be interesting as a studio shot with a monochrome background.</td>', 'Humorous concept. The background is very distracting.  Would be interesting as a studio shot with a monochrome background.', '2007-06-06 09:35:29.000000', NULL, 1),
(3746093, 527562, 45829, '<td valign="top">A humorous concept, but what happened to the focus and lighting?</td>', 'A humorous concept, but what happened to the focus and lighting?', '2007-06-06 09:37:47.000000', NULL, 1),
(3746239, 527260, 68467, '<td valign="top">seems a little overexposed</td>', 'seems a little overexposed', '2007-06-06 10:14:56.000000', NULL, 1),
(3746244, 525835, 68467, '<td valign="top">Awesome capture</td>', 'Awesome capture', '2007-06-06 10:15:46.000000', NULL, 1),
(3746255, 527372, 68467, '<td valign="top">nice capture - a thing that catch my eyes is that the shadows is pointing towards the sun</td>', 'nice capture - a thing that catch my eyes is that the shadows is pointing towards the sun', '2007-06-06 10:18:08.000000', NULL, 1),
(3746260, 527681, 68467, '<td valign="top">nice and clear colors - good job</td>', 'nice and clear colors - good job', '2007-06-06 10:19:45.000000', NULL, 1),
(3746282, 526857, 70270, '<td valign="top">I really like the composition on this one.  Overall sharpness is great.  Lighting is nice, and adds a lot of contrast to the image.  A simple subject, done extremely well.</td>', 'I really like the composition on this one.  Overall sharpness is great.  Lighting is nice, and adds a lot of contrast to the image.  A simple subject, done extremely well.', '2007-06-06 10:24:34.000000', NULL, 1),
(3746284, 527655, 70270, '<td valign="top">Nice colors and lighting, and well seen for the challenge.</td>', 'Nice colors and lighting, and well seen for the challenge.', '2007-06-06 10:24:54.000000', NULL, 1),
(3746288, 527632, 70270, '<td valign="top">Very sharp, and a good moment with the birds looking in opposite directions.  Well lit, too.</td>', 'Very sharp, and a good moment with the birds looking in opposite directions.  Well lit, too.', '2007-06-06 10:25:36.000000', NULL, 1),
(3746293, 526704, 70270, '<td valign="top">Good eye for an interesting subject to tie into this challenge.  A good choice for B+W as well.</td>', 'Good eye for an interesting subject to tie into this challenge.  A good choice for B+W as well.', '2007-06-06 10:26:20.000000', NULL, 1),
(3746300, 525657, 70270, '<td valign="top">Wow -- super sharp, and great lighting.  Its easy to just bounce light off these slimy gastropods, but you''ve managed to capture both the texture and the color wonderfully.  Very well done.</td>', 'Wow -- super sharp, and great lighting.  Its easy to just bounce light off these slimy gastropods, but you''ve managed to capture both the texture and the color wonderfully.  Very well done.', '2007-06-06 10:28:25.000000', NULL, 1),
(3746305, 526102, 70270, '<td valign="top">Two great subjects, well lit.  You''ve managed to tell a story with a still life, rather than just stopping at creating a pretty picture.</td>', 'Two great subjects, well lit.  You''ve managed to tell a story with a still life, rather than just stopping at creating a pretty picture.', '2007-06-06 10:29:31.000000', NULL, 1),
(3746310, 527072, 70270, '<td valign="top">Nicely composed and good definition/separation between the two animals.</td>', 'Nicely composed and good definition/separation between the two animals.', '2007-06-06 10:30:29.000000', NULL, 1),
(3746311, 527284, 70270, '<td valign="top">What a great idea, and a lot of work went into the setup (unless, of course, you just happened to have a large red and white triangle lying around the house!)  I like the general thought and most of the composition, but think this could have been improved by having the two girls holding the triangle hiding behind it, and possibly applying a little blur in post processing to mask them out. You could have cropped a little bit more on the right, too, so the main sign is not so centered.</td>', 'What a great idea, and a lot of work went into the setup (unless, of course, you just happened to have a large red and white triangle lying around the house!)  I like the general thought and most of the composition, but think this could have been improved by having the two girls holding the triangle hiding behind it, and possibly applying a little blur in post processing to mask them out. You could have cropped a little bit more on the right, too, so the main sign is not so centered.', '2007-06-06 10:30:35.000000', NULL, 1),
(3746312, 525515, 70270, '<td valign="top">Lol ... well posed and photographed.  Much harder than it looks, I''m sure.</td>', 'Lol ... well posed and photographed.  Much harder than it looks, I''m sure.', '2007-06-06 10:31:09.000000', NULL, 1),
(3746314, 524359, 70270, '<td valign="top">Interesting image.  The blur works in this composition.</td>', 'Interesting image.  The blur works in this composition.', '2007-06-06 10:31:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3746318, 527514, 70270, '<td valign="top">Very sharp and well lit, but image itself doesn''t mean anything, so is kind of boring to me after the initial "cool" reaction.  Technically excellent though, so it gets a 6 from me.</td>', 'Very sharp and well lit, but image itself doesn''t mean anything, so is kind of boring to me after the initial "cool" reaction.  Technically excellent though, so it gets a 6 from me.', '2007-06-06 10:32:46.000000', NULL, 1),
(3746322, 527199, 70270, '<td valign="top">Nice set up, great location, and a funny shot.  Looks like you had a blast photographing this.</td>', 'Nice set up, great location, and a funny shot.  Looks like you had a blast photographing this.', '2007-06-06 10:33:22.000000', NULL, 1),
(3746324, 526389, 70270, '<td valign="top">Sorta interesting on the first look, but nothing strong enough to hold my interest very long.  Well lit and nicely composed, though.</td>', 'Sorta interesting on the first look, but nothing strong enough to hold my interest very long.  Well lit and nicely composed, though.', '2007-06-06 10:34:24.000000', NULL, 1),
(3746328, 526650, 70270, '<td valign="top">Nice idea, but for some reason the dog on the right looks sharper and better lit to me.  Might just be that you can see life in her eyes, while the eyes on the left are dull in comparison.  Nice composition.  Gave you a 6.</td>', 'Nice idea, but for some reason the dog on the right looks sharper and better lit to me.  Might just be that you can see life in her eyes, while the eyes on the left are dull in comparison.  Nice composition.  Gave you a 6.', '2007-06-06 10:35:49.000000', NULL, 1),
(3746333, 525690, 70270, '<td valign="top">Interesting subject.  Very sharp and I like the black background and frame you''ve used.</td>', 'Interesting subject.  Very sharp and I like the black background and frame you''ve used.', '2007-06-06 10:37:18.000000', NULL, 1),
(3746334, 526322, 70270, '<td valign="top">Nice tight composition; very sharp and well exposed given all the colors in the shot.</td>', 'Nice tight composition; very sharp and well exposed given all the colors in the shot.', '2007-06-06 10:38:03.000000', NULL, 1),
(3746337, 525288, 70270, '<td valign="top">Nice subject, very sharp and I like the colors.  The background is a little distracting, particularly where it pulls into sharper focus around the lower left corner.  Might have been nice for the two flowers to be a little closer together to avoid the largish open space between them in the composition.  6</td>', 'Nice subject, very sharp and I like the colors.  The background is a little distracting, particularly where it pulls into sharper focus around the lower left corner.  Might have been nice for the two flowers to be a little closer together to avoid the largish open space between them in the composition.  6', '2007-06-06 10:39:27.000000', NULL, 1),
(3746345, 525345, 70270, '<td valign="top">Well composed .. I like how you''ve put the one dog very close to the camera where you could really capture his personality, and left the other further back and slightly out of focus.  One nit is that I wish the back dogs left foot was not hidden slightly behind the front dog''s ear, but your subjects don''t look like they were the easiest to control!</td>', 'Well composed .. I like how you''ve put the one dog very close to the camera where you could really capture his personality, and left the other further back and slightly out of focus.  One nit is that I wish the back dogs left foot was not hidden slightly behind the front dog''s ear, but your subjects don''t look like they were the easiest to control!', '2007-06-06 10:41:22.000000', NULL, 1),
(3746351, 526820, 70270, '<td valign="top">Nice composition, though it has the feel of a set up shot to me.  Good choice to use B+W here.</td>', 'Nice composition, though it has the feel of a set up shot to me.  Good choice to use B+W here.', '2007-06-06 10:42:40.000000', NULL, 1),
(3746355, 526763, 70270, '<td valign="top">Nice set up.  Focus is a little soft on the edge of the top pear.  Something about the lighting or processing makes this a tad harsh, but still rates a 6 from me.</td>', 'Nice set up.  Focus is a little soft on the edge of the top pear.  Something about the lighting or processing makes this a tad harsh, but still rates a 6 from me.', '2007-06-06 10:43:45.000000', NULL, 1),
(3746360, 527298, 70270, '<td valign="top">Unique view, and an interesting subject for the challenge.  Lighting, composition, and framing are all spot on for this subject.</td>', 'Unique view, and an interesting subject for the challenge.  Lighting, composition, and framing are all spot on for this subject.', '2007-06-06 10:44:42.000000', NULL, 1),
(3746366, 527148, 70270, '<td valign="top">Great use of a mirror for this shot ... the reflected background really makes you stop and wonder whether there is a mirror here at all.  Nice job.</td>', 'Great use of a mirror for this shot ... the reflected background really makes you stop and wonder whether there is a mirror here at all.  Nice job.', '2007-06-06 10:46:17.000000', NULL, 1),
(3746374, 527415, 70270, '<td valign="top">Cool lighting that fits your subjects, and nice to see someone who realizes that "similar" does not necessarily mean "identical"</td>', 'Cool lighting that fits your subjects, and nice to see someone who realizes that "similar" does not necessarily mean "identical"', '2007-06-06 10:48:18.000000', NULL, 1),
(3746381, 526772, 70270, '<td valign="top">Nicely lit, and wonderful colors.  Would make for a nice greeting card cover shot.</td>', 'Nicely lit, and wonderful colors.  Would make for a nice greeting card cover shot.', '2007-06-06 10:50:12.000000', NULL, 1),
(3746383, 527652, 71958, '<td valign="top">nice shot, i like the effect but it is a little over processed.  missed how it fits the challenge.</td>', 'nice shot, i like the effect but it is a little over processed.  missed how it fits the challenge.', '2007-06-06 10:50:48.000000', NULL, 1),
(3746384, 524360, 70270, '<td valign="top">Good candid shot!  Oh, wait, that''s next week''s challenge.  Nice double take, too.  :&gt;)</td>', 'Good candid shot!  Oh, wait, that''s next week''s challenge.  Nice double take, too.  :>)', '2007-06-06 10:51:02.000000', NULL, 1),
(3746388, 526456, 70270, '<td valign="top">Well lit, but the subject just doesn''t hold my interest very long -- maybe its the smoke/fog at the top that''s too distracting, because normally I like zen-style subjects and images.</td>', 'Well lit, but the subject just doesn''t hold my interest very long -- maybe its the smoke/fog at the top that''s too distracting, because normally I like zen-style subjects and images.', '2007-06-06 10:52:08.000000', NULL, 1),
(3746390, 527551, 70270, '<td valign="top">Good capture, and well exposed -- with all that light bouncing around the sky, you can stil see the texture on the smoke trails.</td>', 'Good capture, and well exposed -- with all that light bouncing around the sky, you can stil see the texture on the smoke trails.', '2007-06-06 10:52:57.000000', NULL, 1),
(3746401, 527696, 70270, '<td valign="top">Great eye for the challenge, very cool scene and colors.  Might have liked you to move just a little to the right to capture more of the front of the second snowman and also avoid cutting off the tree in the background at the edge of the left frame.  6</td>', 'Great eye for the challenge, very cool scene and colors.  Might have liked you to move just a little to the right to capture more of the front of the second snowman and also avoid cutting off the tree in the background at the edge of the left frame.  6', '2007-06-06 10:54:30.000000', NULL, 1),
(3746407, 527120, 71958, '<td valign="top">nice shot, but did i miss the double take?....</td>', 'nice shot, but did i miss the double take?....', '2007-06-06 10:56:32.000000', NULL, 1),
(3746410, 526534, 70270, '<td valign="top">Great shot and perfect subject for this challenge ... I tried to do something similar with the Transamerica Pyramid building in San Francisco for this challenge, so I know its more difficult than it looks.  Wish there was somewhere to set the model to avoid having the hand in the image, but still a cool idea and shot.</td>', 'Great shot and perfect subject for this challenge ... I tried to do something similar with the Transamerica Pyramid building in San Francisco for this challenge, so I know its more difficult than it looks.  Wish there was somewhere to set the model to avoid having the hand in the image, but still a cool idea and shot.', '2007-06-06 10:57:38.000000', NULL, 1),
(3746413, 527619, 71958, '<td valign="top">nice Cake title.  the colors seem a little off... too much cyan?</td>', 'nice Cake title.  the colors seem a little off... too much cyan?', '2007-06-06 10:58:13.000000', NULL, 1),
