(3759127, 526296, 60573, '<td valign="top">Hmm... certainly a picture worth spending a few moments on.  The number plate, the contrasst, the reflections, etc.... Well done!!</td>', 'Hmm... certainly a picture worth spending a few moments on.  The number plate, the contrasst, the reflections, etc.... Well done!!', '2007-06-09 00:01:27.000000', NULL, 1),
