INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3759518, 527386, 31637, '<td valign="top">I have the same bulb on the left! Tesla baby!</td>', 'I have the same bulb on the left! Tesla baby!', '2007-06-09 04:10:36.000000', NULL, 1),
(3759546, 524530, 79663, '<td valign="top">Cool!</td>', 'Cool!', '2007-06-09 05:34:48.000000', NULL, 1),
(3759596, 527417, 70661, '<td valign="top">I remember my grandparents had one of these double out houses at their cabin when I was a kid. I always wondered if I wasn''t supposed to go alone! LOL Nice take on the challenge!</td>', 'I remember my grandparents had one of these double out houses at their cabin when I was a kid. I always wondered if I wasn''t supposed to go alone! LOL Nice take on the challenge!', '2007-06-09 06:50:24.000000', NULL, 1),
(3759664, 527641, 55838, '<td valign="top">Very pretty blues and nice mood in this shot.  Feels like true love to me : )  Love the reflections and I even think the border works great. Back to bump you up to 9.</td>', 'Very pretty blues and nice mood in this shot.  Feels like true love to me : )  Love the reflections and I even think the border works great. Back to bump you up to 9.', '2007-06-09 08:57:20.000000', NULL, 1),
(3759666, 525489, 55838, '<td valign="top">It amazes me how folks get shots of lightning and to get a great "double take" lighning shot to boot!  What are the odds?! Very well done and pleasant to look at.  I love the trees in the foreground too.  Back to bump you up to 9.</td>', 'It amazes me how folks get shots of lightning and to get a great "double take" lighning shot to boot!  What are the odds?! Very well done and pleasant to look at.  I love the trees in the foreground too.  Back to bump you up to 9.', '2007-06-09 08:59:54.000000', NULL, 1),
(3759668, 526534, 55838, '<td valign="top">Back to comment.  This shot is so much fun!  I love that you got just the right distance that your "Eiffels" are the same size.  Nice focus.  Great idea.  Gave this an 8 earlier this week.</td>', 'Back to comment.  This shot is so much fun!  I love that you got just the right distance that your "Eiffels" are the same size.  Nice focus.  Great idea.  Gave this an 8 earlier this week.', '2007-06-09 09:03:43.000000', NULL, 1),
(3759681, 522509, 70661, '<td valign="top">Like the colors and the way you set this up and framed it. 10</td>', 'Like the colors and the way you set this up and framed it. 10', '2007-06-09 09:26:45.000000', NULL, 1),
(3759682, 527152, 70661, '<td valign="top">I can''t help it, I just like old worn things. Great job on processing! 10</td>', 'I can''t help it, I just like old worn things. Great job on processing! 10', '2007-06-09 09:27:34.000000', NULL, 1),
(3759684, 527211, 70661, '<td valign="top">I think the grainyness works here. Nice!</td>', 'I think the grainyness works here. Nice!', '2007-06-09 09:28:10.000000', NULL, 1),
(3759685, 523393, 70661, '<td valign="top">Nice take on the challenge.</td>', 'Nice take on the challenge.', '2007-06-09 09:28:48.000000', NULL, 1),
(3759686, 527632, 70661, '<td valign="top">Colors are great! Good capture! 9</td>', 'Colors are great! Good capture! 9', '2007-06-09 09:29:28.000000', NULL, 1),
(3759689, 527414, 70661, '<td valign="top">Great capture! 10</td>', 'Great capture! 10', '2007-06-09 09:32:07.000000', NULL, 1),
(3759695, 527350, 70661, '<td valign="top">Hmmm...this is one of the strangest photos I''ve ever seen! Great imagination!</td>', 'Hmmm...this is one of the strangest photos I''ve ever seen! Great imagination!', '2007-06-09 09:36:14.000000', NULL, 1),
(3759699, 527149, 70661, '<td valign="top">Love the processing! 10</td>', 'Love the processing! 10', '2007-06-09 09:37:30.000000', NULL, 1),
(3759831, 527242, 36102, '<td valign="top">Nice picture.  I like how blurred out the backgroud is.  I think the cars are a little close to the edge.</td>', 'Nice picture.  I like how blurred out the backgroud is.  I think the cars are a little close to the edge.', '2007-06-09 10:44:53.000000', NULL, 1),
(3759832, 525067, 36102, '<td valign="top">The lighting is a little bright fron the front.  Looks like a camera flash perhaps.  Maybe using a side light as well would help.</td>', 'The lighting is a little bright fron the front.  Looks like a camera flash perhaps.  Maybe using a side light as well would help.', '2007-06-09 10:45:37.000000', NULL, 1),
(3759838, 522509, 36102, '<td valign="top">Very vivid...all the bugs I find are ugly.  Good shot, I like their placement in the frame.</td>', 'Very vivid...all the bugs I find are ugly.  Good shot, I like their placement in the frame.', '2007-06-09 10:47:26.000000', NULL, 1),
(3760340, 525069, 49865, '<td valign="top">Nice, they almost look conjoined. The focus is a little bit soft, but then again, so are the subjects.</td>', 'Nice, they almost look conjoined. The focus is a little bit soft, but then again, so are the subjects.', '2007-06-09 14:01:48.000000', NULL, 1),
(3760343, 527141, 49865, '<td valign="top">Excellent photo. Crisp, nice lighting, and good choice for subject.</td>', 'Excellent photo. Crisp, nice lighting, and good choice for subject.', '2007-06-09 14:02:23.000000', NULL, 1),
(3760348, 526783, 49865, '<td valign="top">I like the choice of subject but you should probably revisit it during different lighting - most of the background is a little bit too blown out.</td>', 'I like the choice of subject but you should probably revisit it during different lighting - most of the background is a little bit too blown out.', '2007-06-09 14:05:34.000000', NULL, 1),
(3760353, 524359, 49865, '<td valign="top">Something about this photo appeals to me, but I can''t quite place it. Most people will probably complain about the motion blur and all, but there''s something about it coupled with the the B&amp;W presentation that I''m enjoying here.</td>', 'Something about this photo appeals to me, but I can''t quite place it. Most people will probably complain about the motion blur and all, but there''s something about it coupled with the the B&W presentation that I''m enjoying here.', '2007-06-09 14:06:29.000000', NULL, 1),
(3760357, 527597, 49865, '<td valign="top">Nice perspective, and good choice of duotones.</td>', 'Nice perspective, and good choice of duotones.', '2007-06-09 14:11:09.000000', NULL, 1),
(3760359, 525515, 49865, '<td valign="top">Haha, nice. At first I was really confused - is that a little statuette? I love the expression on the (real) dog''s face.</td>', 'Haha, nice. At first I was really confused - is that a little statuette? I love the expression on the (real) dog''s face.', '2007-06-09 14:12:13.000000', NULL, 1),
(3760425, 526929, 1024, '<td valign="top">I came back to this one to comment and I have bumped you from a 6 to an 8.  I must not have had my coffee yet.  Simply elegant.</td>', 'I came back to this one to comment and I have bumped you from a 6 to an 8.  I must not have had my coffee yet.  Simply elegant.', '2007-06-09 15:05:42.000000', NULL, 1),
(3760426, 524552, 1024, '<td valign="top">I am not exactly sure what this is, but its interesting enough for me to come back for a better look, and a small bump in your score.</td>', 'I am not exactly sure what this is, but its interesting enough for me to come back for a better look, and a small bump in your score.', '2007-06-09 15:06:37.000000', NULL, 1),
(3760435, 526534, 79242, '<td valign="top">I really thought this was a good photo. It is a good photo, and maybe the best "double take" photo in the bunch. I hope that it does well. Such a simple idea that is executed almost perfectly. I like to offer criticism with every photo, but it is hard with this. hmmmm.....I think the miniature tower is a little out of level..... haha, that''s it. Good job..</td>', 'I really thought this was a good photo. It is a good photo, and maybe the best "double take" photo in the bunch. I hope that it does well. Such a simple idea that is executed almost perfectly. I like to offer criticism with every photo, but it is hard with this. hmmmm.....I think the miniature tower is a little out of level..... haha, that''s it. Good job..', '2007-06-09 15:12:41.000000', NULL, 1),
(3760452, 525515, 79242, '<td valign="top">Wow, the first truly exceptional photo I have come across in the double take category. All I can say is Wow. Great light, good subject matter. An Amazing photo......... I love the light. It is what sets this photo above all the others......Upon further review, this is my favorite shot of the double take challenge. 10</td>', 'Wow, the first truly exceptional photo I have come across in the double take category. All I can say is Wow. Great light, good subject matter. An Amazing photo......... I love the light. It is what sets this photo above all the others......Upon further review, this is my favorite shot of the double take challenge. 10', '2007-06-09 15:20:42.000000', NULL, 1),
(3760455, 526190, 1024, '<td valign="top">This is my choice for the blue ribbon,  it has everything.  Great composition, great exposure, nice bright colors and a dash of humor.  Love the scooter.</td>', 'This is my choice for the blue ribbon,  it has everything.  Great composition, great exposure, nice bright colors and a dash of humor.  Love the scooter.', '2007-06-09 15:23:15.000000', NULL, 1),
(3760472, 526625, 18505, '<td valign="top">Amazing!  Truly makes one want to know the rest of the stories. 10</td>', 'Amazing!  Truly makes one want to know the rest of the stories. 10', '2007-06-09 15:38:02.000000', NULL, 1),
(3760588, 527334, 48697, '<td valign="top">nice abstract of wine glasses</td>', 'nice abstract of wine glasses', '2007-06-09 16:31:44.000000', NULL, 1),
(3760590, 527517, 48697, '<td valign="top">Looks like a cop and his mini-me.. very funny.</td>', 'Looks like a cop and his mini-me.. very funny.', '2007-06-09 16:33:17.000000', NULL, 1),
(3760593, 527542, 48697, '<td valign="top">cool idea but I think a little more seperation between the two might help just a bit, imo.</td>', 'cool idea but I think a little more seperation between the two might help just a bit, imo.', '2007-06-09 16:34:38.000000', NULL, 1),
(3760653, 527261, 48697, '<td valign="top">intresting unique shot! I love the lighting.</td>', 'intresting unique shot! I love the lighting.', '2007-06-09 16:54:43.000000', NULL, 1),
(3760662, 527546, 48697, '<td valign="top">cute photo. I feel the angle you are on distracts a bit from the photo.</td>', 'cute photo. I feel the angle you are on distracts a bit from the photo.', '2007-06-09 16:58:18.000000', NULL, 1),
(3760667, 527692, 48697, '<td valign="top">This a nice photo but the table line in the background that intersects with the subjects distracts a bit imo.</td>', 'This a nice photo but the table line in the background that intersects with the subjects distracts a bit imo.', '2007-06-09 16:59:18.000000', NULL, 1),
(3760669, 527514, 48697, '<td valign="top">reminds me of cell division..good abstract photo.</td>', 'reminds me of cell division..good abstract photo.', '2007-06-09 17:00:12.000000', NULL, 1),
(3760670, 527623, 48697, '<td valign="top">good idea, i do feel the towel is distractiong and it looks like the glass on the right is leaning.</td>', 'good idea, i do feel the towel is distractiong and it looks like the glass on the right is leaning.', '2007-06-09 17:01:22.000000', NULL, 1),
(3760677, 526288, 48697, '<td valign="top">Your photo seems to be lacking contrast and the empty space on the lower right of the frame draws attention away from the flowers.  Maybe a shift to the the left would have helped or a tighter crop.</td>', 'Your photo seems to be lacking contrast and the empty space on the lower right of the frame draws attention away from the flowers.  Maybe a shift to the the left would have helped or a tighter crop.', '2007-06-09 17:03:03.000000', NULL, 1),
(3760693, 527627, 48697, '<td valign="top">nice lighting.</td>', 'nice lighting.', '2007-06-09 17:08:32.000000', NULL, 1),
(3760694, 526534, 47852, '<td valign="top">Good setup to show them at almost the same size in the frame.  I think if there was no writing on the other sides of the miniature, I would have showed that instead to keep it more similar.  Nicely done.</td>', 'Good setup to show them at almost the same size in the frame.  I think if there was no writing on the other sides of the miniature, I would have showed that instead to keep it more similar.  Nicely done.', '2007-06-09 17:08:57.000000', NULL, 1),
(3760698, 525664, 47852, '<td valign="top">Sweet moment... but are they sharing or is the white one stealing? :)  Nice duotone in the sepias, works well here.</td>', 'Sweet moment... but are they sharing or is the white one stealing? :)  Nice duotone in the sepias, works well here.', '2007-06-09 17:10:10.000000', NULL, 1),
(3760703, 525645, 48697, '<td valign="top">intresting water color look, i do think the building in the background takes away from your main focus of the boys.</td>', 'intresting water color look, i do think the building in the background takes away from your main focus of the boys.', '2007-06-09 17:10:52.000000', NULL, 1),
(3760705, 526874, 47852, '<td valign="top">They both look incredibly angry at you for taking their picture!  I like the rays of light streaming down.  Difficult to get good, clear underwater shots... they always look a bit murky I think.</td>', 'They both look incredibly angry at you for taking their picture!  I like the rays of light streaming down.  Difficult to get good, clear underwater shots... they always look a bit murky I think.', '2007-06-09 17:11:15.000000', NULL, 1),
(3760709, 527657, 48697, '<td valign="top">nice photo</td>', 'nice photo', '2007-06-09 17:12:41.000000', NULL, 1),
(3760710, 527325, 47852, '<td valign="top">Good details in the petals and centers, and I like that they''re not the exact same colors.  Seems a bit overprocessed though since they feel like they''re floating above the black, or cut out of the background, and you''ve lost some of the petal tips to the blown out yellows.</td>', 'Good details in the petals and centers, and I like that they''re not the exact same colors.  Seems a bit overprocessed though since they feel like they''re floating above the black, or cut out of the background, and you''ve lost some of the petal tips to the blown out yellows.', '2007-06-09 17:12:41.000000', NULL, 1),
(3760713, 527557, 48697, '<td valign="top">the line of the table runing through the fliter distracts a bit imo.</td>', 'the line of the table runing through the fliter distracts a bit imo.', '2007-06-09 17:13:22.000000', NULL, 1),
(3760715, 527372, 47852, '<td valign="top">Nice idea and a great landscape for this.  The glasses are just a bit lost in the darkness though, but I''m not sure how to fix that.</td>', 'Nice idea and a great landscape for this.  The glasses are just a bit lost in the darkness though, but I''m not sure how to fix that.', '2007-06-09 17:14:03.000000', NULL, 1),
(3760721, 526802, 47852, '<td valign="top">Love the trails they''ve left leading up the leaf.  Good shallow dof, but I still feel like this could use a touch of usm, and maybe a tweak in contrast.</td>', 'Love the trails they''ve left leading up the leaf.  Good shallow dof, but I still feel like this could use a touch of usm, and maybe a tweak in contrast.', '2007-06-09 17:16:12.000000', NULL, 1),
